def hPrimary(self, simulation):
    """Compute primary magnetic field.

    Note that we compute analytic vector potential and take numerical
    curl so that B is divergence-free.

    Parameters
    ----------
    simulation : BaseFDEMSimulation
        A SimPEG FDEM simulation

    Returns
    -------
    numpy.ndarray
        Primary magnetic field
    """
    if simulation._formulation == "1D":
        if getattr(self, "_1d_h", None) is None:
            dipole = self._dipole
            out = []
            for rx in self.receiver_list:
                if rx.use_source_receiver_offset:
                    locs = rx.locations + self.location
                else:
                    locs = rx.locations
                h_rx = dipole.magnetic_field(locs)
                out.append(h_rx @ rx.orientation)
            self._1d_h = out
        return self._1d_h
    b = self.bPrimary(simulation)
    return 1.0 / self.mu * b

def s_m(self, simulation):
    """Magnetic source term (s_m)

    Parameters
    ----------
    simulation : BaseFDEMSimulation
        SimPEG FDEM simulation

    Returns
    -------
    numpy.ndarray
        Magnetic source term on mesh.
    """

    b_p = self.bPrimary(simulation)
    if simulation._formulation == "HJ":
        b_p = simulation.Me * b_p
    return -1j * omega(self.frequency) * b_p

def s_e(self, simulation):
    """Electric source term (s_e)

    Parameters
    ----------
    simulation : BaseFDEMSimulation
        SimPEG FDEM simulation

    Returns
    -------
    numpy.ndarray
        Electric source term on mesh.
    """

    if all(np.r_[self.mu] == np.r_[simulation.mu]):
        return Zero()
    else:
        formulation = simulation._formulation

        if formulation == "EB":
            mui_s = simulation.mui - 1.0 / self.mu
            MMui_s = simulation.mesh.get_face_inner_product(mui_s)
            C = simulation.mesh.edge_curl
        elif formulation == "HJ":
            mu_s = simulation.mu - self.mu
            MMui_s = simulation.mesh.get_edge_inner_product(
                mu_s, invert_matrix=True
            )
            C = simulation.mesh.edge_curl.T

        return -C.T * (MMui_s * self.bPrimary(simulation))

def s_eDeriv(self, simulation, v, adjoint=False):
    if not hasattr(simulation, "muMap") or not hasattr(simulation, "muiMap"):
        return Zero()
    else:
        formulation = simulation._formulation

        if formulation == "EB":
            mui_s = simulation.mui - 1.0 / self.mu
            MMui_sDeriv = (
                simulation.mesh.get_face_inner_product_deriv(mui_s)(
                    self.bPrimary(simulation)
                )
                * simulation.muiDeriv
            )
            C = simulation.mesh.edge_curl

            if adjoint:
                return -MMui_sDeriv.T * (C * v)

            return -C.T * (MMui_sDeriv * v)

        elif formulation == "HJ":
            return Zero()
            # raise NotImplementedError
            mu_s = simulation.mu - self.mu
            MMui_s = simulation.mesh.get_edge_inner_product(
                mu_s, invert_matrix=True
            )
            C = simulation.mesh.edge_curl.T

            return -C.T * (MMui_s * self.bPrimary(simulation))

def _srcFct(self, obsLoc, coordinates="cartesian"):
    if getattr(self, "_dipole", None) is None:
        self._dipole = MagneticDipoleWholeSpace(
            mu=self.mu,
            orientation=self.orientation,
            location=self.location,
            moment=self.moment,
        )
    out = self._dipole.vector_potential(obsLoc, coordinates=coordinates)
    out[np.isnan(out)] = 0
    return out

def _aSrc(self, simulation):
    coordinates = "cartesian"
    if simulation._formulation == "EB":
        gridX = simulation.mesh.gridEx
        gridY = simulation.mesh.gridEy
        gridZ = simulation.mesh.gridEz

    elif simulation._formulation == "HJ":
        gridX = simulation.mesh.gridFx
        gridY = simulation.mesh.gridFy
        gridZ = simulation.mesh.gridFz

    if simulation.mesh._meshType == "CYL":
        coordinates = "cylindrical"
        if simulation.mesh.is_symmetric:
            return self._srcFct(gridY)[:, 1]

    ax = self._srcFct(gridX, coordinates)[:, 0]
    ay = self._srcFct(gridY, coordinates)[:, 1]
    az = self._srcFct(gridZ, coordinates)[:, 2]
    a = np.concatenate((ax, ay, az))

    return a

def _getAmagnetostatic(self, simulation):
    if simulation._formulation == "EB":
        return (
            simulation.mesh.face_divergence
            * simulation.MfMuiI
            * simulation.mesh.face_divergence.T.tocsr()
        )
    else:
        raise NotImplementedError(
            "Solving the magnetostatic simulationlem for the initial fields "
            "when a permeable model is considered has not yet been "
            "implemented for the HJ formulation. "
            "See: https://github.com/simpeg/simpeg/issues/680"
        )

def _rhs_magnetostatic(self, simulation):
    if getattr(self, "_hp", None) is None:
        if simulation._formulation == "EB":
            bp = simulation.mesh.edge_curl * self._aSrc(simulation)
            self._MfMuip = simulation.mesh.get_face_inner_product(1.0 / self.mu)
            self._MfMuipI = simulation.mesh.get_face_inner_product(
                1.0 / self.mu, invert_matrix=True
            )
            self._hp = self._MfMuip * bp
        else:
            raise NotImplementedError(
                "Solving the magnetostatic simulationlem for the initial fields "
                "when a permeable model is considered has not yet been "
                "implemented for the HJ formulation. "
                "See: https://github.com/simpeg/simpeg/issues/680"
            )

    if simulation._formulation == "EB":
        return -simulation.mesh.face_divergence * (
            (simulation.MfMuiI - self._MfMuipI) * self._hp
        )
    else:
        raise NotImplementedError(
            "Solving the magnetostatic simulationlem for the initial fields "
            "when a permeable model is considered has not yet been "
            "implemented for the HJ formulation. "
            "See: https://github.com/simpeg/simpeg/issues/680"
        )

def _phiSrc(self, simulation):
    Ainv = simulation.solver(
        self._getAmagnetostatic(simulation)
    )  # todo: store these
    rhs = self._rhs_magnetostatic(simulation)
    Ainv.clean()
    return Ainv * rhs

def _bSrc(self, simulation):
    if simulation._formulation == "EB":
        C = simulation.mesh.edge_curl

    elif simulation._formulation == "HJ":
        C = simulation.mesh.edge_curl.T

    return C * self._aSrc(simulation)

